function page(r,title,body,status=200){r.status(status).send('<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+' · Pídeme</title><link rel="icon" href="/brand/logo.svg" type="image/svg+xml"><style>'+css+'</style></head><body><header><a href="/"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 44 44" aria-hidden="true"><rect width="44" height="44" rx="13" fill="#e64925"/><path d="M12 19h20l-2 15H14z" fill="#fff4df"/><path d="M17 20v-4a5 5 0 0110 0v4" fill="none" stroke="#fff4df" stroke-width="2.7" stroke-linecap="round"/><path d="m18 26 3 3 6-7" fill="none" stroke="#e64925" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>pídeme<b>.</b></a><nav><a href="/panel">Iniciar sesión</a><a class="nav-cta" href="/registro">Crear tienda</a></nav></header><main>'+body+'</main><footer class="footer">Pídeme · Pedidos directos, sin intermediarios. · <a href="/privacidad">Privacidad</a></footer></body></html>')}
const field=(l,n,v='',t='text',required=false)=>'<label>'+E(l)+'<input name="'+n+'" type="'+t+'" value="'+E(v)+'" '+(required?'required':'')+(t==='number'?' min="0" step="0.01"':'')+'></label>',ck=(l,n,v)=>'<label><input type="checkbox" name="'+n+'" '+(v?'checked':'')+'>'+E(l)+'</label>',btn=x=>'<button>'+E(x)+'</button>',form=(a,c)=>'<form method="post" action="'+a+'">'+c+'</form>',err=(r,m,status=400)=>page(r,'Aviso','<div class="card narrow error"><h2>'+E(m)+'</h2><a href="javascript:history.back()">Volver</a><p><a href="/">Inicio</a></p></div>',status);

const imageOK=x=>!x||/^https:\/\/[^\s]+$/i.test(x)||/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(x);
const photoField=(l,n,v)=>'<label>'+E(l)+'<input type="file" accept="image/*" onchange="loadPhoto(this,\''+n+'\')"><input type="hidden" name="'+n+'" value="'+E(v)+'"><img id="preview-'+n+'" style="max-width:150px;max-height:100px;border-radius:10px;margin-top:8px;'+(v?'':'display:none')+'" src="'+E(v)+'"><button class="secondary" type="button" onclick="this.parentElement.querySelector(\'input[type=hidden]\').value=\'\';document.getElementById(\'preview-'+n+'\').style.display=\'none\'">Quitar imagen</button></label><script>async function loadPhoto(input,n){const f=input.files[0];if(!f)return;try{let img=await createImageBitmap(f),scale=Math.min(1,900/Math.max(img.width,img.height)),c=document.createElement("canvas");c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));let ctx=c.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);let value=c.toDataURL("image/jpeg",.78);input.parentElement.querySelector("input[type=hidden]").value=value;let p=document.getElementById("preview-"+n);p.src=value;p.style.display="block";img.close()}catch(e){alert("No fue posible abrir la fotografía")}}</script>';

