app.post('/login',async(q,r)=>{if(limit(q,'login',10))return err(r,'Intenta más tarde',429);const s=await one('SELECT * FROM shops WHERE email=$1',S(q.body.email,150).toLowerCase());const p=await password(S(q.body.password,200),s?s.pw.split(':')[0]:'dummy');if(!s||p.length!==s.pw.length||!crypto.timingSafeEqual(Buffer.from(p),Buffer.from(s.pw)))return auth(r,false,'Correo o contraseña incorrectos');await sign(r,s.id);r.redirect('/panel')});
