app.get('/exportar',guard,async(q,r)=>{const os=await all('SELECT id,created,customer,phone,mode,status,total FROM orders WHERE shop=$1 ORDER BY created DESC',q.shop.id);const cell=x=>'"'+String(x??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Folio','Fecha','Cliente','Teléfono','Modalidad','Estado','Total MXN'],...os.map(o=>[o.id.slice(0,8),new Date(o.created).toISOString(),o.customer,o.phone,o.mode,o.status,(o.total/100).toFixed(2)])];r.type('text/csv; charset=utf-8').attachment('pedidos-pideme.csv').send('\uFEFF'+rows.map(x=>x.map(cell).join(',')).join('\r\n'))});
